bad_example:
#[repr(C)]
#[derive(Clone, Copy)]
struct PushConstants {
    a: u32,
    b: u32,
    c: u32,
}
// Size = 12 bytes. WGSL expects 16-byte alignment per member in
// uniform address space. wgpu will not catch this at creation time,
// but the GPU will read shifted values, causing silent corruption.

good_example:
#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct PushConstants {
    a: u32,
    b: u32,
    c: u32,
    _padding: u32,  // explicit pad to reach 16 bytes
}
// Size = 16 bytes. Matches WGSL uniform layout expectations.
// bytemuck::Pod + Zeroable zero-initializes padding, avoiding
// undefined bits reaching the GPU.
